(() => {
  const initialItems = [
    {id:'top-rose',name:'Rosewater Blouse',category:'top',emoji:'👚',color:'#f5b5c7',owned:true,rarity:'Common'},
    {id:'top-sun',name:'Sunday Picnic Tee',category:'top',emoji:'👕',color:'#f5d894',owned:true,rarity:'Common'},
    {id:'top-cloud',name:'Cloud Nine Knit',category:'top',emoji:'🧶',color:'#d9c8eb',owned:true,rarity:'Common'},
    {id:'bottom-bloom',name:'Blooming Skirt',category:'bottom',emoji:'🌸',color:'#ed9eb8',owned:true,rarity:'Common'},
    {id:'bottom-denim',name:'Petal Denim',category:'bottom',emoji:'👖',color:'#9bb9dc',owned:true,rarity:'Common'},
    {id:'dress-daydream',name:'Daydream Dress',category:'dress',emoji:'👗',color:'#eaa2bd',owned:true,rarity:'Rare'},
    {id:'dress-lemon',name:'Lemon Meringue',category:'dress',emoji:'👗',color:'#f0d477',owned:true,rarity:'Common'},
    {id:'hair-choco',name:'Chocolate Waves',category:'hair',emoji:'💇🏻‍♀️',color:'#9b6b5b',owned:true,rarity:'Common'},
    {id:'hair-strawberry',name:'Berry Bob',category:'hair',emoji:'💇🏼‍♀️',color:'#df8794',owned:true,rarity:'Rare'},
    {id:'accessory-bow',name:'Sweetheart Bow',category:'accessory',emoji:'🎀',color:'#ed96ad',owned:true,rarity:'Common'},
    {id:'accessory-star',name:'Starry Hair Clips',category:'accessory',emoji:'✨',color:'#f1cf76',owned:true,rarity:'Common'},
    {id:'hat-beret',name:'Peachy Beret',category:'hat',emoji:'🧢',color:'#e6a18f',owned:true,rarity:'Common'},
    {id:'shoe-maryjane',name:'Cherry Mary Janes',category:'shoes',emoji:'👠',color:'#cf718d',owned:false,rarity:'Rare'},
    {id:'accessory-pearl',name:'Pearl Picnic Bag',category:'accessory',emoji:'👜',color:'#e9d8c6',owned:false,rarity:'Rare'},
    {id:'top-lilac',name:'Lilac Puff Sleeves',category:'top',emoji:'👚',color:'#b8a4d6',owned:false,rarity:'Rare'},
    {id:'dress-moon',name:'Moonbeam Tulle',category:'dress',emoji:'👗',color:'#adc9df',owned:false,rarity:'Ultra rare'},
    {id:'hat-flower',name:'Daisy Crown',category:'hat',emoji:'🌼',color:'#f1d36d',owned:false,rarity:'Rare'},
    {id:'accessory-heart',name:'Love Letter Satchel',category:'accessory',emoji:'💌',color:'#f0a3b4',owned:false,rarity:'Common'},
    {id:'bottom-tulle',name:'Cloud Tulle Skirt',category:'bottom',emoji:'🩰',color:'#c5aedb',owned:false,rarity:'Rare'},
    {id:'hair-honey',name:'Honey Bun Updo',category:'hair',emoji:'💆🏼‍♀️',color:'#c49a5e',owned:false,rarity:'Rare'}
  ];
  const defaultEquipped = {'top':'top-rose','bottom':'bottom-bloom','dress':'','hair':'hair-choco','accessory':'accessory-bow','hat':'','shoes':''};
  const tips=['Try a new color combo — your next favorite look might surprise you!','A cute accessory can make an outfit feel totally yours.','Pair a soft color with one bright little pop.','There are no rules in the style studio. Follow your mood!','Layer a skirt with your favorite top for extra charm.'];
  const presets=[{name:'Cherry sweet',ids:['top-rose','bottom-bloom','accessory-bow','hair-choco']},{name:'Sunday sunshine',ids:['dress-lemon','accessory-star','hair-honey']},{name:'Lilac daydream',ids:['top-lilac','bottom-tulle','hat-flower','hair-strawberry']}];
  const state = loadState();
  let activeCategory='all', activeView='studio', toastTimer;
  const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
  function loadState(){try{const saved=JSON.parse(localStorage.getItem('petalpop-save')||'{}');return {coins:Number.isFinite(saved.coins)?saved.coins:1250,items:initialItems.map(x=>({...x,owned:saved.owned?saved.owned.includes(x.id):x.owned})),equipped:{...defaultEquipped,...(saved.equipped||{})},savedLooks:saved.savedLooks||[],dailyClaimed:saved.dailyClaimed||'',name:saved.name||'Mimi',likes:saved.likes||[]}}catch{return {coins:1250,items:initialItems,equipped:{...defaultEquipped},savedLooks:[],dailyClaimed:'',name:'Mimi',likes:[]}}}
  function persist(){localStorage.setItem('petalpop-save',JSON.stringify({coins:state.coins,owned:state.items.filter(x=>x.owned).map(x=>x.id),equipped:state.equipped,savedLooks:state.savedLooks,dailyClaimed:state.dailyClaimed,name:state.name,likes:state.likes}))}
  function categoryLabel(c){return ({top:'Top',bottom:'Bottom',dress:'Dress',hair:'Hair',accessory:'Extra',hat:'Hat',shoes:'Shoes'})[c]||c}
  function ownedItems(){return state.items.filter(x=>x.owned)}
  function currentItem(cat){return state.items.find(x=>x.id===state.equipped[cat])}
  function toast(msg){const el=$('#toast');el.textContent=msg;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2300)}
  function saveStateAndRender(){persist();renderAll()}
  function itemCard(item, compact=false){const equipped=state.equipped[item.category]===item.id;return `<article class="item-card ${equipped?'equipped':''}" data-id="${item.id}" tabindex="0" role="button" aria-label="Try on ${item.name}"><div class="item-art" style="--swatch:${item.color}">${equipped?'<span class="equipped-mark">✓</span>':''}<span class="item-emoji">${item.emoji}</span></div><div class="item-info"><div class="item-name">${item.name}</div><div class="item-type">${categoryLabel(item.category)}</div></div></article>`}
  function renderCloset(){const candidates=ownedItems().filter(x=>activeCategory==='all'||x.category===activeCategory);$('#closet-grid').innerHTML=candidates.slice(0,8).map(x=>itemCard(x)).join('');$('#item-count').textContent=`${ownedItems().length} pieces`;$('#closet-full-grid').innerHTML=ownedItems().map(x=>itemCard(x)).join('');$('#closet-grid').querySelectorAll('.item-card').forEach(bindItem);$('#closet-full-grid').querySelectorAll('.item-card').forEach(bindItem)}
  function bindItem(el){const action=()=>equip(el.dataset.id);el.addEventListener('click',action);el.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();action()}})}
  function equip(id){const item=state.items.find(x=>x.id===id);if(!item||!item.owned)return; if(item.category==='dress'){state.equipped.dress=state.equipped.dress===id?'':id}else{state.equipped[item.category]=state.equipped[item.category]===id?'':id;if(item.category!=='top'&&item.category!=='bottom'){} if(item.category==='top'||item.category==='bottom')state.equipped.dress=''} renderAll();persist()}
  function setFill(selector,color){document.querySelectorAll(selector).forEach(el=>el.setAttribute('fill',color))}
  function drawOutfit(){const dress=currentItem('dress'),top=currentItem('top'),bottom=currentItem('bottom'),hair=currentItem('hair'),shoe=currentItem('shoes');
    const body=document.querySelector('#body'); body.querySelectorAll('path').forEach(p=>p.setAttribute('opacity','1'));
    if(dress){body.querySelectorAll('path').forEach(p=>{p.setAttribute('fill',dress.color);});body.querySelectorAll('path')[1]?.setAttribute('fill','#f2c6af');body.querySelectorAll('path')[2]?.setAttribute('fill','#f2c6af');body.querySelectorAll('path')[3]?.setAttribute('fill',shade(dress.color,-12));}
    else{body.querySelectorAll('path')[0].setAttribute('fill',top?.color||'#f8d7e3');body.querySelectorAll('path')[1].setAttribute('fill','#f2c6af');body.querySelectorAll('path')[2].setAttribute('fill','#f2c6af');body.querySelectorAll('path')[3].setAttribute('fill',shade(top?.color||'#edabc2',-9));body.querySelectorAll('path')[4].setAttribute('stroke','#fff8f8')}
    const legs=document.querySelector('#legs').querySelectorAll('path');legs.forEach(p=>p.setAttribute('fill',bottom?.color||'#f2c6af'));if(!bottom||bottom.category!=='bottom')legs.forEach(p=>p.setAttribute('fill','#f2c6af'));
    setFill('#shoes path',shoe?.color||'#f28d9b');
    if(hair){setFill('#hair-back path',hair.color);setFill('#hair-front path',shade(hair.color,-14))}
    drawAccessories();
  }
  function shade(hex,amount){let c=hex.replace('#','');if(c.length===3)c=c.split('').map(x=>x+x).join('');const num=parseInt(c,16);return '#'+[16,8,0].map(s=>Math.max(0,Math.min(255,((num>>s)&255)+amount)).toString(16).padStart(2,'0')).join('')}
  function clearLayer(id){const el=document.getElementById(id);while(el.firstChild)el.removeChild(el.firstChild);return el}
  function svgEl(tag,attrs){const el=document.createElementNS('http://www.w3.org/2000/svg',tag);Object.entries(attrs).forEach(([k,v])=>el.setAttribute(k,v));return el}
  function drawAccessories(){const hat=clearLayer('hat'),extra=clearLayer('accessory'),hairExtra=clearLayer('hair-accessory');const h=currentItem('hat'),a=currentItem('accessory');if(h){let shape;if(h.id==='hat-flower'){shape=svgEl('path',{d:'M115 73 Q158 23 203 73 Q199 84 160 84 Q126 83 115 73',fill:'#f1d36d',stroke:'#fff8e4','stroke-width':3});hat.appendChild(shape);[0,1,2,3,4].forEach(i=>{const t=svgEl('circle',{cx:139+i*10,cy:66-Math.abs(2-i)*4,r:4,fill:'#fff8e5'});hat.appendChild(t)})}else{hat.appendChild(svgEl('path',{d:'M116 81 Q119 43 159 47 Q201 48 204 81 Q160 72 116 81Z',fill:h.color}));hat.appendChild(svgEl('path',{d:'M104 79 Q159 69 216 81 Q204 92 159 91 Q120 91 104 79Z',fill:shade(h.color,-10)}))}}
    if(a){if(a.id==='accessory-bow'){extra.appendChild(svgEl('path',{d:'M156 68 Q139 50 131 63 Q128 77 156 72 Q174 79 183 66 Q183 53 156 68Z',fill:a.color,stroke:'#fff2f5','stroke-width':2}));extra.appendChild(svgEl('circle',{cx:157,cy:69,r:4,fill:'#fff3f5'}))}else if(a.id==='accessory-star'){[0,1,2].forEach(i=>extra.appendChild(svgEl('text',{x:137+i*20,y:80+(i%2)*5,'font-size':15,fill:a.color},)) .appendChild(document.createTextNode('✦')))}else{extra.appendChild(svgEl('path',{d:'M205 234 Q235 234 238 269 L211 286 Q193 269 205 234Z',fill:a.color,stroke:'#fff','stroke-width':3}));extra.appendChild(svgEl('path',{d:'M207 239 Q213 220 225 231',fill:'none',stroke:'#b89b8c','stroke-width':3}))}}
  }
  function renderCoins(){$('#coin-count').textContent=state.coins.toLocaleString()}
  function renderSaved(){const container=$('#saved-looks');$('#saved-total').textContent=state.savedLooks.length;if(!state.savedLooks.length){container.innerHTML='<div class="empty-saved"><span>♡</span><p>Your next signature look<br>belongs here.</p></div>';return}container.innerHTML=state.savedLooks.slice(0,6).map((look,i)=>`<div class="saved-look" data-index="${i}" title="Tap to wear this look"><div class="saved-look-art">${look.emoji||'👗'}</div><div class="saved-look-name">${escapeHtml(look.name)}</div></div>`).join('');container.querySelectorAll('.saved-look').forEach(el=>el.addEventListener('click',()=>{const look=state.savedLooks[Number(el.dataset.index)];state.equipped={...defaultEquipped,...look.equipped};saveStateAndRender();toast(`Wearing ${look.name}!`)}))}
  function renderShop(){const shop=state.items.filter(x=>!x.owned);$('#shop-grid').innerHTML=shop.map(item=>`<div class="shop-item"><div class="item-art" style="--swatch:${item.color}"><span class="item-emoji">${item.emoji}</span></div><div class="item-name">${item.name}</div><div class="rarity">${item.rarity} · ${item.rarity==='Ultra rare'?'450':'220'} ✦</div><button class="shop-buy" data-buy="${item.id}">Add to closet · ${item.rarity==='Ultra rare'?'450':'220'} ✦</button></div>`).join('')||'<p class="empty-shop">You own everything! Lovely collecting.</p>';$('#shop-grid').querySelectorAll('[data-buy]').forEach(btn=>btn.addEventListener('click',()=>buyItem(btn.dataset.buy)))}
  function renderInspo(){const cards=[['Sunday in bloom','Soft colors for slow mornings.','🌷','#f7e9e9'],['Cloud-soft crush','A lavender kind of day.','☁️','#ece8f7'],['Picnic in the park','Sunny details, happy heart.','🍓','#eff1df']];$('#inspo-grid').innerHTML=cards.map((c,i)=>`<article class="inspo-card"><div class="inspo-image" style="background:linear-gradient(145deg,${c[3]},#fff8f3)"><span class="inspo-person">${c[2]}</span><span class="inspo-hearts">✦　♡</span></div><div class="inspo-copy"><button class="inspo-like" data-like="${i}">${state.likes.includes(i)?'♥':'♡'} ${state.likes.includes(i)?'Loved':'Love'}</button><b>${c[0]}</b><p>${c[1]}</p></div></article>`).join('');$('#inspo-grid').querySelectorAll('[data-like]').forEach(btn=>btn.addEventListener('click',()=>{const id=Number(btn.dataset.like);state.likes=state.likes.includes(id)?state.likes.filter(x=>x!==id):[...state.likes,id];persist();renderInspo()}))}
  function renderAll(){renderCoins();renderCloset();renderSaved();renderShop();renderInspo();drawOutfit();$('#avatar-name').textContent=state.name}
  function buyItem(id){const item=state.items.find(x=>x.id===id);if(!item||item.owned)return;const price=item.rarity==='Ultra rare'?450:220;if(state.coins<price){toast('Not quite enough sparkle coins yet.');return}state.coins-=price;item.owned=true;persist();renderAll();toast(`${item.name} is yours!`)}
  function openModal(content){$('#modal-content').innerHTML=content;$('#modal').classList.remove('hidden')}
  function closeModal(){$('#modal').classList.add('hidden')}
  function dailyGift(){const today=new Date().toISOString().slice(0,10);if(state.dailyClaimed===today){toast('You already claimed today’s sparkle! Come back tomorrow.');return}state.dailyClaimed=today;state.coins+=150;persist();renderAll();openModal('<div class="reward-art">🎁</div><span class="challenge-label">A LITTLE SOMETHING FOR YOU</span><h2>Daily sparkle!</h2><p>You found <b>150 sparkle coins</b> tucked away for you. Come back tomorrow for another little surprise.</p><div class="modal-actions"><button class="primary-btn" id="reward-ok">Lovely, thanks!</button></div>');$('#reward-ok').addEventListener('click',closeModal)}
  function saveLook(){if(state.savedLooks.length>=8){toast('Your lookbook is full — remove a look to make space.');return}const name=`Look ${state.savedLooks.length+1}`;const worn=Object.values(state.equipped).filter(Boolean).map(id=>state.items.find(x=>x.id===id)).filter(Boolean);const emoji=worn.find(x=>x.category==='dress')?.emoji||worn.find(x=>x.category==='top')?.emoji||'👗';state.savedLooks.unshift({name,equipped:{...state.equipped},emoji});persist();renderSaved();toast('Look saved to your little lookbook!')}
  function randomize(){const cats=['top','bottom','dress','hair','accessory','hat'];cats.forEach(cat=>{const options=ownedItems().filter(x=>x.category===cat);state.equipped[cat]=options.length?options[Math.floor(Math.random()*options.length)].id:''});if(state.equipped.dress){state.equipped.top='';state.equipped.bottom=''}else if(!state.equipped.top)state.equipped.top=ownedItems().find(x=>x.category==='top')?.id||'';persist();renderAll();toast('A fresh look, just for you!')}
  function challenge(){const worn=Object.values(state.equipped).filter(Boolean).map(id=>state.items.find(x=>x.id===id)).filter(Boolean);const matching=worn.filter(x=>['#f5b5c7','#ed9eb8','#eaa2bd','#ed96ad'].includes(x.color)).length;const reward=matching>=2?100:50;state.coins+=reward;persist();renderCoins();openModal(`<div class="reward-art">${matching>=2?'🌸':'✨'}</div><span class="challenge-label">CHERRY BLOSSOM DAYDREAM</span><h2>${matching>=2?'You understood the assignment!':'Cute look, lovely start!'}</h2><p>Your outfit earned <b>${matching>=2?'Spring Stylist':'Fresh Take'}</b> and <b>${reward} sparkle coins</b>. ${matching<2?'Try adding a soft pink piece next time for a bonus!':'Those soft spring colors are everything.'}</p><div class="modal-actions"><button class="primary-btn" id="challenge-done">Keep styling</button></div>`);$('#challenge-done').addEventListener('click',closeModal)}
  function pullCapsule(){if(state.coins<300){toast('You need 300 sparkle coins for a capsule.');return}state.coins-=300;const pool=state.items.filter(x=>!x.owned);let reward;if(!pool.length){state.coins+=240;reward=null}else{const roll=Math.random();const rarity=roll<.65?'Common':roll<.94?'Rare':'Ultra rare';const candidates=pool.filter(x=>x.rarity===rarity);reward=(candidates.length?candidates:pool)[Math.floor(Math.random()*(candidates.length?candidates:pool).length)];if(reward)reward.owned=true}persist();renderAll();if(!reward){openModal('<div class="reward-art">✨</div><h2>All collected!</h2><p>You already have every piece in this drop, so you got 240 sparkle coins back.</p><div class="modal-actions"><button class="primary-btn" id="capsule-ok">Yay!</button></div>')}else{openModal(`<div class="reward-art">${reward.emoji}</div><span class="challenge-label">A NEW LITTLE TREASURE</span><h2>${escapeHtml(reward.name)}!</h2><p>${reward.rarity} find! Your new piece is waiting in your closet.</p><div class="modal-actions"><button class="primary-btn" id="capsule-ok">Add to my closet</button></div>`)}$('#capsule-ok').addEventListener('click',closeModal)}
  function escapeHtml(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
  function switchView(view){activeView=view;$$('.nav-link').forEach(b=>b.classList.toggle('active',b.dataset.view===view));$('#view-studio').classList.toggle('hidden',view!=='studio');$$('.page-view').forEach(x=>x.classList.add('hidden'));if(view!=='studio')$(`#view-${view}`).classList.remove('hidden');if(view==='closet')renderCloset();window.scrollTo({top:0,behavior:'smooth'})}
  $$('.nav-link').forEach(btn=>btn.addEventListener('click',()=>switchView(btn.dataset.view)));
  $$('.category-tab').forEach(btn=>btn.addEventListener('click',()=>{$$('.category-tab').forEach(x=>x.classList.remove('selected'));btn.classList.add('selected');activeCategory=btn.dataset.category;renderCloset()}));
  $('#daily-gift').addEventListener('click',dailyGift);$('#save-look-btn').addEventListener('click',saveLook);$('#randomize-btn').addEventListener('click',randomize);$('#challenge-btn').addEventListener('click',challenge);$('#pull-btn').addEventListener('click',pullCapsule);$('#earn-coins').addEventListener('click',()=>{switchView('shop');toast('Open a capsule or style the daily prompt to earn sparkle!')});$('#see-all-btn').addEventListener('click',()=>switchView('closet'));$('#modal-close').addEventListener('click',closeModal);$('#modal').addEventListener('click',e=>{if(e.target.id==='modal')closeModal()});$('#tip-btn').addEventListener('click',()=>{const p=$('.tip-card p');p.innerHTML=`<b>A little style tip</b><br>${tips[Math.floor(Math.random()*tips.length)]}`});$('#pose-btn').addEventListener('click',()=>{$('#avatar').classList.toggle('pose-pop')});$('#rename-btn').addEventListener('click',()=>{const value=prompt('What should we call your avatar?',state.name);if(value&&value.trim()){state.name=value.trim().slice(0,16);persist();$('#avatar-name').textContent=state.name}});$('#clear-saved').addEventListener('click',()=>{if(!state.savedLooks.length){toast('Your lookbook is already empty.');return}if(confirm('Clear your saved looks?')){state.savedLooks=[];persist();renderSaved();toast('Lookbook cleared.')}});$('#mobile-menu').addEventListener?.('click',()=>{});
  $('#challenge-btn').addEventListener('click',challenge);
  $('#view-studio').addEventListener('click',e=>{const el=e.target.closest('.item-card');if(el&&el.dataset.id)equip(el.dataset.id)});
  renderAll();
})();

