import { createRequire } from 'node:module'
const require = createRequire('/home/runner/.local/share/omgithub-playwright/package.json')
const { chromium } = require('playwright')
const browser = await chromium.launch({ headless: true, executablePath: '/usr/bin/chromium', args: ['--no-sandbox'] })
const page = await browser.newPage({ viewport: { width: 1280, height: 900 } })
const errors = []
page.on('pageerror', e => errors.push(e.message))
await page.goto('http://localhost:3002/', { waitUntil: 'load' })
const checks = []
const check = async (label, fn) => { await fn(); checks.push(label) }
await check('initial studio and item render', async () => {
  if (!(await page.locator('#closet-grid .item-card').count())) throw new Error('closet is empty')
  if ((await page.locator('#coin-count').innerText()) !== '1,250') throw new Error('wallet did not initialize')
})
await check('equip owned item', async () => {
  await page.locator('#closet-grid [data-id="top-sun"]').click()
  if (!(await page.locator('#closet-grid [data-id="top-sun"]').evaluate(el => el.classList.contains('equipped')))) throw new Error('top was not equipped')
})
await check('save and restore look', async () => {
  await page.locator('#save-look-btn').click()
  if ((await page.locator('#saved-total').innerText()) !== '1') throw new Error('look did not save')
  await page.locator('#randomize-btn').click()
  await page.locator('.saved-look').click()
  if (!(await page.locator('#closet-grid [data-id="top-sun"]').evaluate(el => el.classList.contains('equipped')))) throw new Error('look did not restore')
})
await check('shop navigation and purchase', async () => {
  await page.locator('[data-view="shop"]').click()
  await page.locator('[data-buy="shoe-maryjane"]').click()
  if (!(await page.locator('#shop-grid [data-buy="shoe-maryjane"]').count() === 0)) throw new Error('purchase not reflected')
})
await check('capsule reward modal', async () => {
  await page.locator('#pull-btn').click()
  if (await page.locator('#modal').evaluate(el => el.classList.contains('hidden'))) throw new Error('capsule modal did not open')
  await page.locator('#capsule-ok').click()
})
await check('inspiration likes', async () => {
  await page.locator('[data-view="inspiration"]').click()
  await page.locator('[data-like="0"]').click()
  if (!(await page.locator('[data-like="0"]').innerText()).includes('Loved')) throw new Error('like was not toggled')
})
await check('daily gift modal', async () => {
  await page.locator('[data-view="studio"]').click()
  await page.locator('#daily-gift').click()
  if (!(await page.locator('#modal h2').innerText()).includes('Daily sparkle')) throw new Error('daily gift modal did not appear')
  await page.locator('#reward-ok').click()
})
await check('no page errors', async () => { if (errors.length) throw new Error(errors.join('; ')) })
console.log(JSON.stringify({ checks, errors, coins: await page.locator('#coin-count').innerText() }, null, 2))
await browser.close()
EOF
