import { createRequire } from 'node:module'
const require = createRequire('/home/runner/.local/share/omgithub-playwright/package.json')
const { chromium } = require('playwright')
const browser = await chromium.launch({ headless: true, executablePath: '/usr/bin/chromium', args: ['--no-sandbox'] })
const context = await browser.newContext({ viewport: { width: 1280, height: 900 } })
const page = await context.newPage()
const errors = []
page.on('pageerror', e => errors.push(e.message))
await page.goto('http://localhost:3002/', { waitUntil: 'load' })
const checks = []
const check = async (label, fn) => { await fn(); checks.push(label) }
await check('initial studio, date, and closet render', async () => {
  if (!(await page.locator('#closet-grid .item-card').count())) throw new Error('closet is empty')
  if ((await page.locator('#coin-count').innerText()) !== '1,250') throw new Error('wallet did not initialize')
  if ((await page.locator('#today-date').innerText()).includes('MAY 20')) throw new Error('date is still hard-coded')
})
await check('equip owned item', async () => {
  await page.locator('#closet-grid [data-id="top-sun"]').click()
  if (!(await page.locator('#closet-grid [data-id="top-sun"]').evaluate(el => el.classList.contains('equipped')))) throw new Error('top was not equipped')
})
await check('save and restore look', async () => {
  await page.locator('#save-look-btn').click()
  if ((await page.locator('#saved-total').innerText()) !== '1') throw new Error('look did not save')
  await page.locator('#randomize-btn').click()
  await page.locator('.saved-look').click()
  if (!(await page.locator('#closet-grid [data-id="top-sun"]').evaluate(el => el.classList.contains('equipped')))) throw new Error('look did not restore')
})
await check('shop navigation and purchase', async () => {
  await page.locator('[data-view="shop"]').click()
  await page.locator('[data-buy="shoe-maryjane"]').click()
  if (await page.locator('#shop-grid [data-buy="shoe-maryjane"]').count()) throw new Error('purchase not reflected')
})
await check('capsule duplicate conversion', async () => {
  await page.evaluate(() => { Math.random = () => 0 })
  const before = Number((await page.locator('#coin-count').innerText()).replace(',', ''))
  await page.locator('#pull-btn').click()
  if (!(await page.locator('#modal-content').innerText()).includes('60 sparkle coins')) throw new Error('duplicate reward did not explain coin conversion')
  const after = Number((await page.locator('#coin-count').innerText()).replace(',', ''))
  if (after !== before - 240) throw new Error(`expected 300 cost less 60 duplicate refund, got ${before} to ${after}`)
  await page.locator('#capsule-ok').click()
})
await check('daily style prompt can be claimed once', async () => {
  await page.locator('[data-view="studio"]').click()
  await page.locator('#challenge-btn').click()
  if (!(await page.locator('#challenge-btn').isDisabled())) throw new Error('prompt button remained enabled')
  if (!(await page.locator('#modal h2').innerText()).length) throw new Error('prompt reward did not open')
  await page.locator('#challenge-done').click()
  const saved = await page.evaluate(() => JSON.parse(localStorage.getItem('petalpop-save')))
  if (!saved.challengeClaimed) throw new Error('prompt claim was not persisted')
  await page.reload()
  if (!(await page.locator('#challenge-btn').isDisabled())) throw new Error('prompt claim did not persist across reload')
})
await check('inspiration likes', async () => {
  await page.locator('[data-view="inspiration"]').click()
  await page.locator('[data-like="0"]').click()
  if (!(await page.locator('[data-like="0"]').innerText()).includes('Loved')) throw new Error('like was not toggled')
})
await check('daily gift modal and once-per-day guard', async () => {
  await page.locator('[data-view="studio"]').click()
  await page.locator('#daily-gift').click()
  if (!(await page.locator('#modal h2').innerText()).includes('Daily sparkle')) throw new Error('daily gift modal did not appear')
  await page.locator('#reward-ok').click()
  const before = await page.locator('#coin-count').innerText()
  await page.locator('#daily-gift').click()
  if (await page.locator('#coin-count').innerText() !== before) throw new Error('daily gift was awarded twice')
})
await check('mobile navigation', async () => {
  await page.setViewportSize({ width: 390, height: 844 })
  await page.locator('#mobile-menu').click()
  if (!(await page.locator('.main-nav').evaluate(el => el.classList.contains('mobile-open')))) throw new Error('mobile menu did not open')
  await page.locator('[data-view="shop"]').click()
  if (await page.locator('#view-shop').evaluate(el => el.classList.contains('hidden'))) throw new Error('mobile navigation failed')
})
await check('no page errors', async () => { if (errors.length) throw new Error(errors.join('; ')) })
console.log(JSON.stringify({ checks, errors }, null, 2))
const fresh = await browser.newPage({ viewport: { width: 1280, height: 900 } })
await fresh.goto('http://localhost:3002/', { waitUntil: 'load' })
await fresh.screenshot({ path: '/tmp/opencode/petal-pop-final.jpg', type: 'jpeg', quality: 84 })
await browser.close()
